 function reporting(bank){
  if(bank?.bank_id!=='CB-GRAM-001'||bank.source_version===reportingVersion)return bank;
  const prior=appearance(bank);
  const items=prior.items.map(original=>{
   const patch=reportingReview[original.content_item_id];if(!patch)return original;
   const item={...structuredClone(original),...structuredClone(patch),version:reportingVersion,qa_id:'ER_REPORTING_REVIEW_20260923'};
   item.source_ref={...item.source_ref,original_cefr_level:'B2'};
   if(patch.model_answer)item.correct_answer=item.model_answer;
   if(item.options.length)item.options=item.options.map(x=>x[0].toUpperCase()+x.slice(1));
   if(['meerkeuze_vorm','meerkeuze_context'].includes(item.exercise_type))item.prompt='Welke hele zin klopt?';
   item.feedback_correct='Bespreek waarom het antwoord past.';item.feedback_incorrect=item.explanation;
   item.feedback={correct:item.feedback_correct,incorrect:item.feedback_incorrect};
   const n=Number(item.content_item_id.slice(-3));
   item.practice_group='er-informatie-'+(n===121||n===133||n===145||n===149?'signalen':n===122||n===134||n===142||n===150?'mogelijkheid':n===123||n===131||n===139?'onvolledig':n===124||n===135||n===140?'melding':n===127||n===137?'hulp':n===128||n===136||n===148?'verwachting':n===129||n===141||n===143?'controle':n===132||n===144?'aanname':n);
   return item;
  });
  return {...prior,source_version:reportingVersion,source_sha256:'b6b3d74f1cd31f38fed8738e76c6f49f17ef4880f656bb1002c1ee17ad21c1ad',qa_id:'ER_REPORTING_REVIEW_20260923',items};
 }
